 M4("If the temperature rises from −4°C by 7°C it becomes:", "3°C", ["−11°C", "11°C", "−3°C"], "$-4+7$"),
 M4("If the temperature falls from 2°C by 6°C it becomes:", "−4°C", ["4°C", "8°C", "−8°C"], "$2-6$"),
 M4("Debt of ₹50 is shown as:", "−50", ["50", "0", "+5"], "negative amount"),
