for a, b in [(8, -3), (-6, -4), (-9, 4), (5, -8), (-7, 7), (12, -15), (-2, -9), (10, -4), (-11, 6), (4, -10)]:
    r = a + b
    A.append(M4(f"The value of ${sg(a)}+({sg(b)})$ is:", sg(r), [sg(-r) if r else "1", sg(r + 2), sg(r - 2)], "add integers using signs"))
A = A[:40]
assert len(A) == 40, len(A)
